require_once __DIR__.'/../_bootstrap.php';$u=user();$d=body();required($d,['current_password','new_password']);if(strlen($d['new_password'])<6)fail('New password must be at least 6 characters.');$q=db()->prepare('SELECT password FROM users WHERE id=?');$q->execute([$u['id']]);$account=$q->fetch();if(!$account||!password_verify($d['current_password'],$account['password']))fail('Current password is incorrect.',400);db()->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($d['new_password'],PASSWORD_DEFAULT),$u['id']]);out(['success'=>true,'message'=>'Password changed successfully.']);
